import { tag } from './setup.ts';
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { sql, closeDb } from '@aihot/backend/db';
import { createReview, reviewDetail, saveReview, decideReview, reconcileReviews, generatedReviewDraft, ReviewModelDraft, QualityVerdict, qualityAllowsPublication, nextAutomaticReviews } from '@aihot/backend/admin/upstream-reviews';
const dir=await mkdtemp(join(tmpdir(),'review-test-'));
process.env.UPSTREAM_REVIEW_CACHE=join(dir,'snapshot.json');
const t=tag();const id='draft-'+t;
const original='https://example.com/'+t;
let material={id,title:'来源标题',summary:'原样引用 <script>alert(1)</script> & 保留标点。',links:{aihot:'https://aihot.news/items/'+id,original},attribution:{name:'AIHOT',url:'https://aihot.news/items/'+id},source:{name:'Original'},category:'industry',score:91,selected:true,publishedAt:new Date().toISOString()};
let items:Record<string,unknown>={[id]:material};
let removed:string[]=[];
async function snapshot(age=0){await writeFile(process.env.UPSTREAM_REVIEW_CACHE!,JSON.stringify({checkedAt:new Date(Date.now()-age).toISOString(),complete:true,items,removed}));}
const draft={title:'审批标题',summary:'仅根据所附材料做有条件的分析，不声称已经独立查阅原文。',analysis:'这些变化的影响取决于实际开放范围、价格与现有工作流适配。材料没有给出独立测试，采用前需要核对原始发布信息。',uncertainties:'未独立核验原文、价格与可用性。'};
const checks={facts:true,addedValue:true,duplicates:true};
after(async()=>{delete process.env.UPSTREAM_REVIEW_CACHE;await rm(dir,{recursive:true,force:true});await closeDb();});
test('drafts stay private, approvals preserve quotations, conflicts and changes revoke publication',async()=>{
 const verdict=QualityVerdict.parse({decision:'approve',factsSupported:true,addedValue:true,duplicate:false,reason:'有条件分析，引用支持'});
 assert.equal(qualityAllowsPublication(verdict),true);
 for(const change of [{decision:'hold' as const},{factsSupported:false},{addedValue:false},{duplicate:true}])
   assert.equal(qualityAllowsPublication({...verdict,...change}),false);
 assert.equal(generatedReviewDraft({...draft,analysis:'处理状态：代理已达到最大步骤数，未使用外部工具。\n\n'+draft.analysis}).analysis,draft.analysis);
 assert.equal(generatedReviewDraft(draft).analysis,draft.analysis);
 assert.equal(ReviewModelDraft.parse({...draft,uncertainties:['问题一','问题二']}).uncertainties,'问题一\n问题二');
 assert.throws(()=>ReviewModelDraft.parse({...draft,uncertainties:[{},'invalid']}));
 await snapshot();const created=(await createReview(id,'test:editor'))!;
 assert.equal(created.status,'draft');assert.equal((await sql`SELECT * FROM publications WHERE article_id=${'review-'+id}`).length,0);
 const detail=(await reviewDetail(id))!;
 await assert.rejects(saveReview(id,{version:created.version+1,sourceHash:detail.currentHash,draft},'test:editor'),/草稿已变化/);
 const saved=(await saveReview(id,{version:created.version,sourceHash:detail.currentHash,draft,source:{summary:'tampered'}},'test:editor'))!;
 assert.equal(saved.source.summary,material.summary);
 await assert.rejects(decideReview(id,{version:saved.version,decision:'approve',reason:'reviewed'},'test:editor'),/请确认/);
 const approved=await decideReview(id,{version:saved.version,decision:'approve',reason:'事实及新增价值已检查',selected:true,checks},'test:editor');
 assert.equal(approved!.status,'approved');
 const [publicRow]=await sql`SELECT p.visibility,p.eligible,p.selected,p.score,a.body_text,a.body_html,a.published_at FROM publications p JOIN articles a ON a.id=p.article_id WHERE p.article_id=${'review-'+id}`;
 assert.equal(publicRow!.visibility,'public');assert.equal(publicRow!.eligible,true);assert.equal(publicRow!.selected,true);assert.equal(publicRow!.score,null);
 assert.ok(publicRow!.body_text.includes(material.summary));assert.ok(!publicRow!.body_html.includes('<script>'));assert.ok(publicRow!.body_html.includes('&lt;script&gt;'));
 assert.equal(publicRow!.published_at.toISOString(),material.publishedAt);
 await assert.rejects(decideReview(id,{version:saved.version,decision:'approve',reason:'double click',checks},'test:editor'),/草稿已变化/);
 const second={...material,id:'duplicate-'+t,links:{...material.links,aihot:'https://aihot.news/items/duplicate-'+t}};
 items[second.id]=second;await snapshot();const d=(await createReview(second.id,'test:editor'))!;const dd=(await reviewDetail(second.id))!;
 const ds=(await saveReview(second.id,{version:d.version,sourceHash:dd.currentHash,draft},'test:editor'))!;
 await assert.rejects(decideReview(second.id,{version:ds.version,decision:'approve',reason:'duplicate',checks},'test:editor'),/同一原文/);
 material={...material,summary:'来源已更正：与旧说法不同。'};items[id]=material;await snapshot();
 await assert.rejects(saveReview(id,{version:approved!.version,sourceHash:detail.currentHash,draft},'test:editor'),/来源已变化/);
 assert.equal((await reconcileReviews()).changed,1);
 const [withdrawn]=await sql`SELECT visibility,selected FROM publications WHERE article_id=${'review-'+id}`;
 assert.equal(withdrawn!.visibility,'withdrawn');
 const changed=(await reviewDetail(id))!;assert.equal(changed.row.status,'stale');
 const corrected=(await saveReview(id,{version:changed.row.version,sourceHash:changed.currentHash,draft},'test:editor'))!;
 const republished=await decideReview(id,{version:corrected.version,decision:'approve',reason:'重新审阅',checks},'test:editor');
 delete items[id];await snapshot();assert.equal((await reconcileReviews()).changed,0);
 assert.equal((await sql`SELECT visibility FROM publications WHERE article_id=${'review-'+id}`)[0]!.visibility,'public');
 removed=[id];await snapshot();await reconcileReviews();
 assert.equal((await reviewDetail(id))!.row.status,'withdrawn');
 assert.equal((await sql`SELECT visibility FROM publications WHERE article_id=${'review-'+id}`)[0]!.visibility,'withdrawn');
 await assert.rejects(decideReview(id,{version:republished!.version+1,decision:'approve',reason:'source gone',checks},'test:editor'),/来源已变化/);
 await snapshot(61*60_000);await assert.rejects(createReview(second.id,'test:editor'),/超过一小时/);
 assert.ok((await sql`SELECT * FROM audit_log WHERE subject=${'upstream-review:'+id}`).length>=6);
});
test('automatic batches skip existing drafts, old materials and duplicate originals; AI approval is labelled honestly',async()=>{
 const fresh={...material,id:'auto-'+t,publishedAt:new Date().toISOString(),summary:'一份具有足够细节的近期材料，用于检查自动批次仅处理新材料，不覆盖手动修改或旧稿件。',
   links:{aihot:'https://aihot.news/items/auto-'+t,original:'https://example.com/auto-'+t}};
 const old={...fresh,id:'old-'+t,publishedAt:new Date(Date.now()-8*86400_000).toISOString()};
 const duplicate={...fresh,id:'same-'+t,links:{...fresh.links,original}};
 const unknownDate={...fresh,id:'undated-'+t,publishedAt:null};
 items={[fresh.id]:fresh,[old.id]:old,[duplicate.id]:duplicate,[unknownDate.id]:unknownDate};removed=[];
 await snapshot();assert.deepEqual(await nextAutomaticReviews(3),[fresh.id]);
 const row=(await createReview(fresh.id,'test:batch'))!;
 assert.deepEqual(await nextAutomaticReviews(3),[]);
 const detail=(await reviewDetail(fresh.id))!;
 const saved=(await saveReview(fresh.id,{version:row.version,sourceHash:detail.currentHash,draft},'test:batch'))!;
 await decideReview(fresh.id,{version:saved.version,decision:'approve',reason:'AI独立复核通过',checks},'local:opencode:review','ai');
 const [published]=await sql`SELECT tags,selected,score FROM publications WHERE article_id=${'review-'+fresh.id}`;
 assert.ok(published!.tags.includes('AI复核'));assert.ok(!published!.tags.includes('人工审阅'));
 assert.equal(published!.selected,false);assert.equal(published!.score,null);
 items[fresh.id]={...fresh,summary:fresh.summary+' 更正'};await snapshot();
 await reconcileReviews();assert.deepEqual(await nextAutomaticReviews(3),[fresh.id]);
});
